class Solution {
  public boolean isSubstringPresent(String s) {
    boolean[][] seen = new boolean[26][26];
    for (int i = 1; i < s.length(); i++) {
      int a = s.charAt(i - 1) - 'a';
      int b = s.charAt(i) - 'a';
      seen[a][b] = true;
    }
    for (int a = 0; a < 26; a++) {
      for (int b = 0; b < 26; b++) {
        if (seen[a][b] && seen[b][a]) return true;
      }
    }
    return false;
  }
}
